const rpc=process.env.RPC_URL;
async function call(m,p){const r=await fetch(rpc,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:m,params:p})});return r.json();}
const w='GsjxJjVWwH8FsHJEgYJ6wUMdJM1S66ErEiukYDB4tVLJ';
const PUMP='6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P';
const sig=await call('getSignaturesForAddress',[w,{limit:12}]);
for(const s of (sig.result||[])){
  const tx=await call('getTransaction',[s.signature,{maxSupportedTransactionVersion:0,encoding:'jsonParsed'}]);
  const r=tx.result;
  if(!r){console.log('SIG',s.signature,'no tx');continue;}
  const logs=(r.meta&&r.meta.logMessages)||[];
  const pumpLogs=logs.filter(l=>l.includes('pump')||l.includes('Program log')||l.includes('failed')||l.includes('Error'));
  console.log('=== SIG',s.signature,'slot',s.slot,'err',r.meta&&r.meta.err?JSON.stringify(r.meta.err):'ok');
  for(const l of pumpLogs.slice(0,25))console.log('   ',l);
}
const acc=await call('getAccountInfo',[PUMP,{encoding:'base64'}]);
console.log('PUMP program owner',acc.result&&acc.result.value&&acc.result.value.owner,'executable',acc.result&&acc.result.value&&acc.result.value.executable);

const rpc=process.env.RPC_URL;
async function call(m,p){const r=await fetch(rpc,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:m,params:p})});return r.json();}
const w='GsjxJjVWwH8FsHJEgYJ6wUMdJM1S66ErEiukYDB4tVLJ';
const PUMP='6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P';
const b=await call('getBalance',[w]); console.log('SOL',b.result&&b.result.value);
const sig=await call('getSignaturesForAddress',[w,{limit:40}]);
const mints=new Set();
for(const s of (sig.result||[])){
  const tx=await call('getTransaction',[s.signature,{maxSupportedTransactionVersion:0,encoding:'jsonParsed'}]);
  const r=tx.result; if(!r) continue;
  const post=(r.meta&&r.meta.postTokenBalances)||[];
  for(const x of post) if(x.mint) mints.add(x.mint);
}
console.log('candidate mints',[...mints]);
for(const m of mints){
  const g=await call('getProgramAccounts',[PUMP,{encoding:'jsonParsed',filters:[{memcmp:{offset:8,bytes:m}}]}]);
  const arr=(g.result||[]);
  console.log('CURVE for',m,'count',arr.length);
  for(const a of arr) console.log('  ',a.pubkey,JSON.stringify(a.account.data));
}

const rpc=process.env.RPC_URL;
async function call(m,p){const r=await fetch(rpc,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:m,params:p})});return r.json();}
const w='GsjxJjVWwH8FsHJEgYJ6wUMdJM1S66ErEiukYDB4tVLJ';
const PUMP='6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P';
const b=await call('getBalance',[w]); console.log('SOL',b.result&&b.result.value);
// find bonding curves where creator == wallet (creator at offset 57)
const g=await call('getProgramAccounts',[PUMP,{encoding:'base64',filters:[{memcmp:{offset:57,bytes:w}}],dataSlice:{offset:8,length:49}}]);
const arr=(g.result||[]);
console.log('curves by creator:',arr.length);
for(const a of arr){
  const d=Buffer.from(a.account.data[0],'base64');
  const vt=d.readBigUInt64LE(0), vs=d.readBigUInt64LE(8), rt=d.readBigUInt64LE(16), rs=d.readBigUInt64LE(24), ts=d.readBigUInt64LE(32);
  const complete=d.readUInt8(40);
  console.log('CURVE',a.pubkey,'vt',vt.toString(),'vs',vs.toString(),'rt',rt.toString(),'rs',rs.toString(),'supply',ts.toString(),'complete',complete);
}
// also list token accounts again
for(const pid of ['TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA']){
  const ta=await call('getTokenAccountsByOwner',[w,{programId:pid},{encoding:'jsonParsed'}]);
  for(const a of (ta.result&&ta.result.value||[])){console.log('TA',a.pubkey,JSON.stringify(a.account.data.parsed.info.tokenAmount),a.account.data.parsed.info.mint);}
}

const rpc=process.env.RPC_URL;
async function call(m,p){const r=await fetch(rpc,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:m,params:p})});return r.json();}
const w='GsjxJjVWwH8FsHJEgYJ6wUMdJM1S66ErEiukYDB4tVLJ';
const b=await call('getBalance',[w]); console.log('SOL',b.result&&b.result.value);
const sig=await call('getSignaturesForAddress',[w,{limit:10}]);
for(const s of (sig.result||[])){
  const tx=await call('getTransaction',[s.signature,{maxSupportedTransactionVersion:0,encoding:'jsonParsed'}]);
  const r=tx.result; if(!r){console.log('SIG',s.signature,'null');continue;}
  const logs=(r.meta&&r.meta.logMessages)||[];
  const instr=(r.transaction&&r.transaction.message&&r.transaction.message.instructions)||[];
  const progs=[...new Set(instr.map(i=>i.programId).filter(Boolean))];
  console.log('SIG',s.signature,'slot',s.slot,'err',r.meta&&r.meta.err?JSON.stringify(r.meta.err):'ok');
  console.log('  progs',progs.join(','));
  for(const l of logs) if(l.includes('Instruction:')||l.includes('failed')||l.includes('Error')||l.includes('Program log: ')) console.log('   ',l);
  const post=(r.meta&&r.meta.postTokenBalances)||[];
  for(const x of post) console.log('  POSTBAL',x.mint,'owner',x.owner,'amt',x.uiTokenAmount&&x.uiTokenAmount.uiAmountString);
}
